(() => {
  if (window.__rail) return 'ready'
  const INK = 0.175
  const cy = (el) => { const b = el.getBoundingClientRect(); return (b.top + b.bottom) / 2 }
  const textInk = (el) => { const r = document.createRange(); r.selectNodeContents(el); const b = r.getBoundingClientRect(); return { right: b.right, cy: (b.top + b.bottom) / 2 } }
  const iconInk = (svg) => { const b = svg.getBoundingClientRect(); return { right: b.right - INK * b.height, cy: (b.top + b.bottom) / 2, size: b.height } }
  const textNodeOf = (slot) => [...slot.children].find((c) => c.textContent.trim().length > 0 && !String(c.className).includes('sr-only'))
  const measure = () => {
    const items = []
    const push = (kind, label, ink, rowEl, hitEl) => {
      const hit = hitEl ? hitEl.getBoundingClientRect() : null
      items.push({
        kind,
        label: String(label).replace(/\s+/g, ' ').trim().slice(0, 14),
        ink: +ink.right.toFixed(2),
        cy: +ink.cy.toFixed(2),
        rowCy: rowEl ? +cy(rowEl).toFixed(2) : null,
        hitW: hit ? +hit.width.toFixed(1) : null,
        hitH: hit ? +hit.height.toFixed(1) : null,
        size: ink.size === undefined ? null : ink.size
      })
    }
    const counts = (sel, kind, rowSel) => {
      for (const slot of document.querySelectorAll(sel)) {
        const t = textNodeOf(slot)
        if (!t) continue
        push(kind, t.textContent, textInk(t), slot.closest(rowSel), null)
      }
    }
    counts('aside nav [data-sidebar-count]', 'nav', 'button')
    counts('[data-sidebar-group] [data-sidebar-count]', 'group', '[data-sidebar-group]')
    counts('[data-sidebar-tag] [data-sidebar-count]', 'tag', '[data-sidebar-tag]')
    for (const key of ['groups', 'views', 'tags']) {
      const head = document.querySelector('[data-sidebar-head="' + key + '"]')
      if (!head) continue
      const svg = head.querySelector('svg')
      if (svg) push('head-' + key, key, iconInk(svg), head.parentElement, head)
      else push('head-' + key, head.textContent, textInk(head), head.parentElement, head)
    }
    for (const btn of document.querySelectorAll('[data-sidebar-menu]')) {
      const svg = btn.querySelector('svg')
      if (!svg) continue
      const row = btn.closest('[data-sidebar-group],[data-sidebar-tag]') || btn.parentElement
      push('menu-' + (btn.getAttribute('data-sidebar-menu') || 'row'), '', iconInk(svg), row, btn)
    }
    const aside = document.querySelector('aside').getBoundingClientRect()
    const firstCount = document.querySelector('[data-sidebar-group] [data-sidebar-count]')
    const tabular = firstCount ? getComputedStyle(textNodeOf(firstCount) || firstCount).fontVariantNumeric : ''
    return { aside: { w: +aside.width.toFixed(2), right: +aside.right.toFixed(2) }, items, tabular }
  }
  const check = (label) => {
    const m = measure()
    const fail = (msg) => { throw new Error('[' + label + '] ' + msg) }
    const need = (k, n) => { const got = m.items.filter((i) => i.kind === k).length; if (got < n) fail('样本不足 ' + k + '=' + got + '（需要 ' + n + '）') }
    need('nav', 3); need('group', 2); need('tag', 2); need('menu-group', 1)
    for (const k of ['head-groups', 'head-views']) if (!m.items.some((i) => i.kind === k)) fail('缺少头部按钮 ' + k)
    const rights = m.items.map((i) => i.ink)
    const spread = Math.max(...rights) - Math.min(...rights)
    const rail = Math.min(...rights)
    if (spread > 1) fail('右轨墨迹未对齐，最大差值 ' + spread.toFixed(2) + 'px: ' + JSON.stringify(m.items.map((i) => i.kind + '=' + i.ink)))
    const rows = m.items.filter((i) => i.rowCy !== null)
    const dyMax = Math.max(...rows.map((i) => Math.abs(i.cy - i.rowCy)))
    const dyBad = rows.filter((i) => Math.abs(i.cy - i.rowCy) > 1).map((i) => i.kind + ':' + (i.cy - i.rowCy).toFixed(2))
    if (dyMax > 1) fail('垂直中心与行中心偏差 ' + dyMax.toFixed(2) + 'px: ' + JSON.stringify(dyBad))
    for (const item of m.items) {
      if (item.kind.startsWith('head-') || item.kind.startsWith('menu-')) {
        if (item.hitH !== null && Math.abs(item.hitH - 24) > 0.5) fail(item.kind + ' 热区高度应为 24，实际 ' + item.hitH)
        if (item.size !== null) {
          if (Math.abs(item.hitW - 24) > 0.5) fail(item.kind + ' 热区应为 24×24，实际 ' + item.hitW + '×' + item.hitH)
          if (Math.abs(item.size - 14) > 0.01) fail(item.kind + ' 图标应为 14px，实际 ' + item.size)
        }
      }
    }
    if (!m.tabular.includes('tabular-nums')) fail('计数未使用等宽数字: ' + m.tabular)
    const offset = m.aside.right - rail
    if (Math.abs(offset - 23.25) > 0.8) fail('轨道线距侧栏右缘应为 23.25px（1 边框 + 8 容器 + 12 行内 + 2.45 描边），实际 ' + offset.toFixed(2))
    return {
      label,
      asideWidth: m.aside.w,
      railInk: +rail.toFixed(2),
      railOffset: +offset.toFixed(2),
      spread: +spread.toFixed(2),
      dyMax: +dyMax.toFixed(2),
      samples: m.items.length,
      icons: m.items.filter((i) => i.size !== null).length,
      table: m.items.map((i) => i.kind + ' @x' + i.ink + ' y' + i.cy + (i.rowCy === null ? '' : ' row' + i.rowCy))
    }
  }
  window.__rail = { measure, check }
  return 'ready'
})()

(async () => {
  const res = await window.api.settings.update({ sidebarWidth: 200 })
  if (!res.ok) throw new Error('settings.update(sidebarWidth=200) 失败: ' + JSON.stringify(res.error))
  const end = Date.now() + 3000
  for (;;) {
    const got = Math.round(document.querySelector('aside').getBoundingClientRect().width)
    if (got === 200) return { width: got }
    if (Date.now() > end) throw new Error('侧栏宽度未变为 200，实际 ' + got)
    await new Promise((r) => setTimeout(r, 60))
  }
})()

