(async () => {
  const res = await window.api.settings.update({ theme: 'light' })
  if (!res.ok) throw new Error('settings.update(theme) 失败: ' + JSON.stringify(res.error))
  const end = Date.now() + 3000
  for (;;) {
    if (document.documentElement.dataset.theme === 'light') return { theme: 'light' }
    if (Date.now() > end) throw new Error('主题未切换为 light，实际 ' + document.documentElement.dataset.theme)
    await new Promise((r) => setTimeout(r, 60))
  }
})()

