(async () => {
  const waitFor = async (fn, ms = 3000) => { const end = Date.now() + ms; for (;;) { const v = fn(); if (v) return v; if (Date.now() > end) return null; await new Promise((r) => setTimeout(r, 60)) } }
  const aside = document.querySelector('aside')
  if (!(await waitFor(() => Math.round(aside.getBoundingClientRect().width) === 56))) throw new Error('折叠态宽度应为 56，实际 ' + aside.getBoundingClientRect().width)
  const counts = document.querySelectorAll('[data-sidebar-count]').length
  if (counts !== 0) throw new Error('折叠态不应残留计数槽: ' + counts)
  const plus = aside.querySelector('button[aria-label="新建分组"]')
  if (!plus) throw new Error('折叠态缺少新建分组入口')
  const svg = plus.querySelector('svg')
  const p = plus.getBoundingClientRect()
  const s = svg.getBoundingClientRect()
  const asideRect = aside.getBoundingClientRect()
  const dx = (s.left + s.right) / 2 - (asideRect.left + asideRect.right) / 2
  const dy = (s.top + s.bottom) / 2 - (p.top + p.bottom) / 2
  if (Math.abs(dx) > 1.5) throw new Error('折叠态加号未水平居中，偏 ' + dx.toFixed(2))
  if (Math.abs(dy) > 1.5) throw new Error('折叠态加号未在按钮内垂直居中，偏 ' + dy.toFixed(2))
  return { width: Math.round(asideRect.width), counts, dx: +dx.toFixed(2), dy: +dy.toFixed(2), hit: Math.round(p.width) + 'x' + Math.round(p.height) }
})()
